import sys,pickle,time
import numpy as np
from sklearn.ensemble import HistGradientBoostingRegressor
from threadpoolctl import threadpool_limits
import conditional_calibration as c
import spatial_calibration as s
import research_validation as r

def design(f,t,n,b,mode,graph=None):
 x=c._residual_tree_design(f,t,n,b)
 base=f['base']
 tc,nc,gap=t-base,n-base,n-t
 def broad(v):return np.broadcast_to(v,base.shape)
 def average(v):return broad(np.mean(v,axis=1,keepdims=True))
 if mode=='trajectory':
  extra=[average(tc),average(nc),average(gap),gap-average(gap),
         broad(tc[:,-1:]-tc[:,:1]),broad(nc[:,-1:]-nc[:,:1])]
 elif mode=='persistent_gap':
  extra=[average(gap),gap-average(gap)]
 elif mode=='spatial':
  if graph is None:graph=s._neighborhood(f)
  def aggregate(v):return np.sum((v/graph['scale'])[...,graph['neighbors']]*graph['weights'],axis=-1)*graph['scale']
  extra=[aggregate(gap),aggregate(b-base),aggregate(nc)]
 elif mode=='trajectory_spatial':
  if graph is None:graph=s._neighborhood(f)
  ng=np.sum((gap/graph['scale'])[...,graph['neighbors']]*graph['weights'],axis=-1)*graph['scale']
  extra=[average(gap),gap-average(gap),ng]
 elif mode=='slope':
  extra=[np.gradient(tc,axis=1),np.gradient(nc,axis=1),np.gradient(gap,axis=1)]
 else:raise ValueError(mode)
 return np.column_stack([x]+[v.reshape(-1) for v in extra]).astype(np.float32)

if __name__=='__main__':
 start=time.monotonic()
 with threadpool_limits(limits=1):
  for split in ['last','middle']:
   with open('/tmp/forecast_turn_residual/'+split+'.cache','rb') as inp:q=pickle.load(inp)
   graph=s._neighborhood(q['ft'])
   valid=np.isfinite(q['yt'])&(q['yt']>0)
   print(split,'control',r.mae(q['yv'],q['control']),flush=True)
   output={}
   for mode in ['persistent_gap','trajectory','spatial','trajectory_spatial','slope']:
    xt=design(q['ft'],q['to'],q['no'],q['oo'],mode,graph)
    xv=design(q['fv'],q['tree'],q['network'],q['blend'],mode,graph)
    model=HistGradientBoostingRegressor(loss='absolute_error',max_iter=40,learning_rate=0.05,max_leaf_nodes=7,min_samples_leaf=2000,l2_regularization=50,categorical_features=[1],early_stopping=False,random_state=17)
    model.fit(xt[valid.ravel()],(q['yt']-q['oo'])[valid])
    correction=np.clip(model.predict(xv).reshape(q['blend'].shape),-10,10)
    pred=np.maximum(q['blend']+0.5*correction,0)
    score=r.mae(q['yv'],pred)
    print(split,mode,'MAE',score,'elapsed',round(time.monotonic()-start,1),flush=True)
    output[mode]={'model':model,'prediction':pred,'mae':score}
   with open('/tmp/forecast_turn_residual/'+split+'.designs','wb') as out:pickle.dump(output,out)
